style.css:
/* Tanjiro Water Breathing Cursor — paste your Base64 where _base64_ is */
body {
  cursor: url("data:image/png;base64,") 5 2, auto;
}

/* Click shimmer effect */
body:active {
  animation: clickShimmer 0.4s ease-out;
}

@keyframes clickShimmer {
  0% {
    filter: brightness(1);
    transform: scale(1);
  }
  50% {
    filter: brightness(1.6);
    transform: scale(1.1);
  }
  100% {
    filter: brightness(1);
    transform: scale(1);
  }
}
